INSERT OR IGNORE INTO products (part_number, category, price, published, sort_order, data) VALUES ('ARDUINO-NANO', 'Boards', 850, 1, 1, '{"part_number":"ARDUINO-NANO","manufacturer":"Arduino","mpn":"ARDUINO-NANO","name":"ATmega328P board, 5 V logic","category":"Boards","price":850,"currency":"PKR","stock_qty":12,"package_type":"DIP-30 module","mounting_type":"Through-hole","voltage":"5 V logic, 7–12 V in","summary":"ATmega328P board with 5 V logic, 14 digital pins, 8 analog inputs, and Mini-B USB.","key_specs":["Logic voltage","Clock","Digital I/O","Analog inputs"],"logic_level":"5 V","specs":[{"label":"Microcontroller","value":"ATmega328P"},{"label":"Logic voltage","value":"5","unit":"V"},{"label":"3.3 V pin","value":"3.3","unit":"V"},{"label":"Digital I/O","value":"14"},{"label":"Analog inputs","value":"8"},{"label":"USB connector","value":"Mini-B"},{"label":"Clock","value":"16","unit":"MHz"},{"label":"Input voltage","value":"7–12","unit":"V"},{"label":"Package","value":"DIP-30 module"},{"label":"Mounting","value":"Through-hole"}],"pinout":[{"pin":"D0","label":"RX"},{"pin":"D1","label":"TX"},{"pin":"D2","label":"Digital"},{"pin":"D3","label":"Digital","note":"PWM"},{"pin":"D4","label":"Digital"},{"pin":"D5","label":"Digital","note":"PWM"},{"pin":"D6","label":"Digital","note":"PWM"},{"pin":"D7","label":"Digital"},{"pin":"D8","label":"Digital"},{"pin":"D9","label":"Digital","note":"PWM"},{"pin":"D10","label":"Digital","note":"PWM"},{"pin":"D11","label":"Digital","note":"PWM"},{"pin":"D12","label":"Digital"},{"pin":"D13","label":"Digital","note":"Built-in LED"},{"pin":"A0","label":"Analog"},{"pin":"A1","label":"Analog"},{"pin":"A2","label":"Analog"},{"pin":"A3","label":"Analog"},{"pin":"A4","label":"Analog","note":"I2C SDA"},{"pin":"A5","label":"Analog","note":"I2C SCL"},{"pin":"A6","label":"Analog","note":"Analog only"},{"pin":"A7","label":"Analog","note":"Analog only"},{"pin":"VIN","label":"Input","note":"7–12 V"},{"pin":"+5V","label":"5 V"},{"pin":"+3V3","label":"3.3 V output"},{"pin":"AREF","label":"Analog reference"},{"pin":"RESET","label":"Reset","note":"Active low. Both headers have one"},{"pin":"GND","label":"Ground","note":"Both headers have one"}],"not_included":"No USB cable.","faq":[{"q":"What logic voltage are the I/O pins?","a":"5 V. The 3.3 V pin is a separate supply pin, not the logic level."},{"q":"How many pins does it bring out?","a":"14 digital I/O pins and 8 analog inputs. A6 and A7 are analog only."},{"q":"What is VIN?","a":"7–12 V, from the Arduino Nano pinout."},{"q":"What is the clock?","a":"16 MHz."},{"q":"What is in the bag?","a":"The board in an antistatic bag. No USB cable."},{"q":"What USB connector is it?","a":"Mini-B."}],"datasheet":"https://docs.arduino.cc/resources/datasheets/A000005-datasheet.pdf","images":[{"src":"asset:parts/cutouts/arduino-nano.webp","alt":"ARDUINO-NANO board with a Mini-B USB socket, a crystal marked 16.000, and unsoldered header holes.","note":"Representative studio photograph, not a photo of the lot in the drawer."}],"in_the_bag":"Board in an antistatic bag.","min_qty":1,"qty_multiple":1,"description":"Arduino Nano V3 with an ATmega328P at 16 MHz. Mini-B USB, 14 digital I/O pins, 8 analog inputs, 5 V logic, a 3.3 V pin, and a 7–12 V VIN pin. Sourced from Hall Road, Lahore."}');
INSERT OR IGNORE INTO stock (part_number, qty) VALUES ('ARDUINO-NANO', 12);
INSERT OR IGNORE INTO products (part_number, category, price, published, sort_order, data) VALUES ('DS18B20', 'Sensors', 220, 1, 2, '{"part_number":"DS18B20","manufacturer":"Analog Devices","mpn":"DS18B20","name":"1-Wire temperature sensor, TO-92","category":"Sensors","price":220,"currency":"PKR","stock_qty":24,"package_type":"TO-92","mounting_type":"Through-hole","voltage":"3.0–5.5 V","summary":"Measures −55 °C to +125 °C on a 1-Wire bus, from 3.0–5.5 V.","key_specs":["Temperature range","Temperature accuracy","Supply voltage","Interface"],"logic_level":"3.3 V and 5 V","specs":[{"label":"Interface","value":"1-Wire"},{"label":"Supply voltage","value":"3.0–5.5","unit":"V"},{"label":"Temperature range","value":"−55 to +125","unit":"°C"},{"label":"Temperature accuracy","value":"±0.5 °C from −10 °C to +85 °C"},{"label":"Address","value":"64-bit"},{"label":"Package","value":"TO-92"},{"label":"Mounting","value":"Through-hole"}],"pinout":[{"pin":"1","label":"GND","note":"Ground"},{"pin":"2","label":"DQ","note":"1-Wire data, open drain"},{"pin":"3","label":"VDD","note":"Ground this pin for parasite power"}],"not_included":"No pull-up resistor. Not the waterproof probe.","faq":[{"q":"What does it measure?","a":"−55 °C to +125 °C. Accuracy is ±0.5 °C from −10 °C to +85 °C."},{"q":"What supply does it use?","a":"3.0–5.5 V, so the bus works at 3.3 V and at 5 V."},{"q":"Can several share one wire?","a":"Yes. Each sensor has its own 64-bit address."},{"q":"Does the bag include a pull-up?","a":"No. DQ is open drain. The datasheet drawing uses 4.7 kΩ, and the text calls the bus pull-up about 5 kΩ."},{"q":"What is pin 3 in parasite power?","a":"Ground. The datasheet says VDD must be grounded in parasite-power mode."},{"q":"Is this the waterproof probe?","a":"No. The bag is a loose TO-92. A waterproof probe is a different part."}],"datasheet":"https://www.analog.com/media/en/technical-documentation/data-sheets/ds18b20.pdf","images":[{"src":"asset:parts/cutouts/ds18b20.webp","alt":"DS18B20 sensor in a TO-92 package, black body with three metal leads.","note":"Representative studio photograph, not a photo of the lot in the drawer."}],"in_the_bag":"Loose TO-92 in an antistatic bag.","min_qty":1,"qty_multiple":1,"description":"DS18B20 1-Wire thermometer in TO-92. −55 °C to +125 °C, ±0.5 °C from −10 °C to +85 °C. Each sensor has a 64-bit address, so more than one can share a bus. DQ needs a pull-up, which is not in the bag. A waterproof probe is a different part, available on request. Sourced from Hall Road, Lahore."}');
INSERT OR IGNORE INTO stock (part_number, qty) VALUES ('DS18B20', 24);
INSERT OR IGNORE INTO products (part_number, category, price, published, sort_order, data) VALUES ('ESP32-WROOM-32D', 'Boards', 1250, 1, 3, '{"part_number":"ESP32-WROOM-32D","manufacturer":"Espressif","mpn":"ESP32-WROOM-32D","name":"Wi-Fi and Bluetooth module, 3.3 V","category":"Boards","price":1250,"currency":"PKR","stock_qty":9,"package_type":"Module","mounting_type":"SMD","voltage":"3.0–3.6 V","summary":"Wi-Fi and Bluetooth module on a 3.0–3.6 V supply, with 3.3 V I/O.","key_specs":["Supply voltage","Flash","Processor","Radio"],"logic_level":"3.3 V","specs":[{"label":"Supply voltage","value":"3.0–3.6","unit":"V"},{"label":"Logic voltage","value":"3.3","unit":"V"},{"label":"Radio","value":"Wi-Fi 802.11 b/g/n, Bluetooth 4.2"},{"label":"Processor","value":"Dual-core Xtensa LX6"},{"label":"Flash","value":"4","unit":"MB"},{"label":"Package","value":"Module"},{"label":"Mounting","value":"SMD"}],"pinout":[{"pin":"1","label":"GND","note":"Ground"},{"pin":"2","label":"3V3","note":"Power supply"},{"pin":"3","label":"EN","note":"Active high"},{"pin":"4","label":"SENSOR_VP","note":"GPIO36, input only"},{"pin":"5","label":"SENSOR_VN","note":"GPIO39, input only"},{"pin":"6","label":"IO34","note":"GPIO34, input only"},{"pin":"7","label":"IO35","note":"GPIO35, input only"},{"pin":"8","label":"IO32","note":"GPIO32"},{"pin":"9","label":"IO33","note":"GPIO33"},{"pin":"10","label":"IO25","note":"GPIO25"},{"pin":"11","label":"IO26","note":"GPIO26"},{"pin":"12","label":"IO27","note":"GPIO27"},{"pin":"13","label":"IO14","note":"GPIO14"},{"pin":"14","label":"IO12","note":"GPIO12"},{"pin":"15","label":"GND","note":"Ground"},{"pin":"16","label":"IO13","note":"GPIO13"},{"pin":"17","label":"SHD/SD2","note":"GPIO9, connected to the module flash"},{"pin":"18","label":"SWP/SD3","note":"GPIO10, connected to the module flash"},{"pin":"19","label":"SCS/CMD","note":"GPIO11, connected to the module flash"},{"pin":"20","label":"SCK/CLK","note":"GPIO6, connected to the module flash"},{"pin":"21","label":"SDO/SD0","note":"GPIO7, connected to the module flash"},{"pin":"22","label":"SDI/SD1","note":"GPIO8, connected to the module flash"},{"pin":"23","label":"IO15","note":"GPIO15"},{"pin":"24","label":"IO2","note":"GPIO2, boot mode"},{"pin":"25","label":"IO0","note":"GPIO0, boot mode"},{"pin":"26","label":"IO4","note":"GPIO4"},{"pin":"27","label":"IO16","note":"GPIO16"},{"pin":"28","label":"IO17","note":"GPIO17"},{"pin":"29","label":"IO5","note":"GPIO5"},{"pin":"30","label":"IO18","note":"GPIO18"},{"pin":"31","label":"IO19","note":"GPIO19"},{"pin":"32","label":"NC","note":"No connection"},{"pin":"33","label":"IO21","note":"GPIO21"},{"pin":"34","label":"RXD0","note":"GPIO3, U0RXD"},{"pin":"35","label":"TXD0","note":"GPIO1, U0TXD"},{"pin":"36","label":"IO22","note":"GPIO22"},{"pin":"37","label":"IO23","note":"GPIO23"},{"pin":"38","label":"GND","note":"Ground"}],"companions":["AMS1117-3.3"],"not_included":"No USB port and no pin headers.","faq":[{"q":"What supply does it need?","a":"3.0–3.6 V. The I/O is 3.3 V, not 5 V."},{"q":"What radio and processor does it have?","a":"Wi-Fi 802.11 b/g/n, Bluetooth 4.2, and a dual-core Xtensa LX6. Flash is 4 MB."},{"q":"Which antenna is on the 32D?","a":"A PCB antenna. This part is not the 32U, which uses an antenna connector."},{"q":"Which pins are tied to the flash?","a":"Pins 17 to 22, GPIO6 to GPIO11. The datasheet says not to use them for anything else."},{"q":"What is in the bag?","a":"The module in an antistatic bag. No USB port and no pin headers."},{"q":"What else on the counter can feed it?","a":"AMS1117-3.3, the 3.3 V regulator."}],"datasheet":"https://documentation.espressif.com/esp32-wroom-32d_esp32-wroom-32u_datasheet_en.pdf","images":[{"src":"asset:parts/cutouts/esp32.webp","alt":"ESP32-WROOM-32D module with a metal shield, a PCB antenna, and castellated pads.","note":"Representative studio photograph, not a photo of the lot in the drawer."}],"in_the_bag":"Module in an antistatic bag.","limits":"I/O is 3.3 V logic.","min_qty":1,"qty_multiple":1,"description":"ESP32-WROOM-32D Wi-Fi and Bluetooth module. Dual-core Xtensa LX6, 4 MB flash, PCB antenna, supply 3.0–3.6 V. I/O is 3.3 V. Sourced from Hall Road, Lahore."}');
